css:
:root {
    --mt-purple: #6f2dbd;
    --mt-purple-dark: #4b1d8f;
    --mt-purple-deep: #2b0c57;
    --mt-lavender: #efe7ff;
    --mt-lavender-2: #f7f2ff;
    --mt-gold: #ffd84d;
    --mt-gold-deep: #f0c62b;
    --mt-white: #ffffff;
    --mt-text: #2d1854;
    --mt-muted: #6d5b8f;
    --mt-border: #e3d6fa;
    --mt-border-strong: #cdb6f5;
    --mt-shadow: 0 1px 2px rgba(43, 12, 87, 0.05), 0 8px 24px rgba(75, 29, 143, 0.08);
    --mt-shadow-strong: 0 14px 35px rgba(43, 12, 87, 0.20);
    --mt-success: #15803d;
    --mt-success-bg: #e8f7ee;
    --mt-warn: #a16207;
    --mt-warn-bg: #fff6d9;
    --mt-danger: #b42318;
    --mt-danger-bg: #fdecea;
    --mt-navbar-offset: calc(var(--np-navbar-height, 60px) + 16px);
}

/* ---------- Page ---------- */

.inventory-dashboard-mt {
    min-height: 100vh;
    background:
        radial-gradient(1200px 400px at 100% -10%, rgba(255, 216, 77, 0.14), transparent 60%),
        radial-gradient(900px 500px at -10% 0%, rgba(111, 45, 189, 0.08), transparent 60%),
        linear-gradient(180deg, #fbf8ff 0%, #f3ecfd 100%);
    color: var(--mt-text);
    font-variant-numeric: tabular-nums;
}

.inventory-dashboard-mt .text-end {
    text-align: right;
}

.mt-shell {
    max-width: 1680px;
    margin: 0 auto;
    padding: 24px 24px 96px;
}

.dashboard-card {
    background: var(--mt-white);
    border: 1px solid var(--mt-border);
    border-radius: 18px;
    box-shadow: var(--mt-shadow);
}

/* ---------- Top bar ---------- */

.mt-topbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    flex-wrap: wrap;
    margin-bottom: 22px;
}

.mt-brand {
    display: flex;
    align-items: center;
    gap: 14px;
    min-width: 0;
}

.mt-brand-mark {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    flex: none;
    border-radius: 14px;
    background: linear-gradient(135deg, var(--mt-purple) 0%, var(--mt-purple-deep) 100%);
    color: var(--mt-gold);
    box-shadow: 0 10px 22px rgba(75, 29, 143, 0.28);
}

.dashboard-title {
    margin: 0;
    font-size: 28px;
    font-weight: 900;
    letter-spacing: -0.5px;
    color: var(--mt-purple-deep);
}

.dashboard-subtitle {
    font-size: 14px;
    color: var(--mt-muted);
}

/* ---------- Layout ---------- */

.mt-layout {
    display: grid;
    grid-template-columns: 280px minmax(0, 1fr);
    gap: 22px;
    align-items: start;
}

.mt-main {
    min-width: 0;
}

/* ---------- Sidebar ---------- */

.sidebar-card {
    position: sticky;
    top: var(--mt-navbar-offset);
    overflow: hidden;
}

.sidebar-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 16px 18px;
    background: linear-gradient(135deg, var(--mt-purple-deep) 0%, var(--mt-purple) 100%);
    color: var(--mt-white);
}

.sidebar-title {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    font-weight: 900;
    letter-spacing: 0.2px;
}

.sidebar-title svg {
    color: var(--mt-gold);
}

.toggle-icon {
    display: none;
    font-size: 12px;
}

.sidebar-body {
    padding: 12px;
    max-height: calc(100vh - var(--mt-navbar-offset) - 80px);
    overflow-y: auto;
}

.sidebar-body.collapsed {
    display: none;
}

.group-search-wrap {
    position: relative;
    margin-bottom: 10px;
}

.group-search-wrap svg {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--mt-muted);
    pointer-events: none;
}

.group-search {
    width: 100%;
    height: 38px;
    padding: 0 12px 0 34px;
    border: 1px solid var(--mt-border);
    border-radius: 10px;
    background: var(--mt-lavender-2);
    color: var(--mt-text);
    font-size: 13px;
    outline: none;
}

.group-search:focus {
    border-color: var(--mt-purple);
    background: var(--mt-white);
    box-shadow: 0 0 0 3px rgba(111, 45, 189, 0.15);
}

.group-list-container {
    display: flex;
    flex-direction: column;
    gap: 4px;
}

.item-group-btn {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 8px;
    width: 100%;
    padding: 10px 12px 10px 14px;
    border: 1px solid transparent;
    border-radius: 10px;
    background: transparent;
    color: var(--mt-text);
    font-size: 14px;
    font-weight: 700;
    text-align: left;
    cursor: pointer;
    transition: background 0.15s ease, color 0.15s ease;
}

.item-group-btn[hidden] {
    display: none;
}

.item-group-btn:hover {
    background: var(--mt-lavender-2);
    color: var(--mt-purple);
}

.item-group-btn:focus-visible {
    outline: none;
    border-color: var(--mt-purple);
    box-shadow: 0 0 0 3px rgba(111, 45, 189, 0.15);
}

.ig-chevron {
    flex: none;
    opacity: 0;
    color: var(--mt-purple);
    transition: opacity 0.15s ease, transform 0.15s ease;
}

.item-group-btn:hover .ig-chevron {
    opacity: 0.6;
}

.item-group-btn.active {
    background: var(--mt-lavender);
    color: var(--mt-purple-deep);
    font-weight: 900;
}

.item-group-btn.active::before {
    content: "";
    position: absolute;
    left: 0;
    top: 8px;
    bottom: 8px;
    width: 4px;
    border-radius: 0 4px 4px 0;
    background: var(--mt-purple);
}

.item-group-btn.active .ig-chevron {
    opacity: 1;
    transform: translateX(2px);
}

.group-empty {
    padding: 14px 8px;
    text-align: center;
    font-size: 13px;
    color: var(--mt-muted);
}

.group-empty[hidden] {
    display: none;
}

/* ---------- Group heading ---------- */

.selected-group-wrap {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: 12px;
    flex-wrap: wrap;
    margin-bottom: 16px;
}

.mt-eyebrow {
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.8px;
    text-transform: uppercase;
    color: var(--mt-purple);
}

.selected-group-text {
    margin: 2px 0 0;
    font-size: 24px;
    font-weight: 900;
    letter-spacing: -0.3px;
    color: var(--mt-purple-deep);
}

.selected-group-actions {
    display: flex;
    align-items: center;
    gap: 10px;
}

/* ---------- Buttons ---------- */

.mt-export-btn,
.mt-reset-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 8px;
    height: 40px;
    padding: 0 16px;
    border-radius: 12px;
    font-weight: 800;
    font-size: 14px;
    transition: background 0.15s ease, border-color 0.15s ease, color 0.15s ease;
}

.mt-export-btn {
    border: 1px solid var(--mt-gold-deep);
    background: linear-gradient(135deg, #fff8dd 0%, var(--mt-gold) 100%);
    color: var(--mt-purple-deep);
}

.mt-export-btn:hover,
.mt-export-btn:focus-visible {
    background: var(--mt-gold-deep);
    color: var(--mt-purple-deep);
}

.mt-reset-btn {
    border: 1px solid var(--mt-border);
    background: var(--mt-white);
    color: var(--mt-purple-dark);
}

.mt-reset-btn:hover,
.mt-reset-btn:focus-visible {
    border-color: var(--mt-purple);
    background: var(--mt-lavender-2);
    color: var(--mt-purple);
}

/* ---------- Summary ---------- */

.summary-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 14px;
    margin-bottom: 16px;
}

.summary-card {
    position: relative;
    display: flex;
    align-items: center;
    gap: 14px;
    padding: 18px;
    overflow: hidden;
}

.summary-card::after {
    content: "";
    position: absolute;
    right: -30px;
    top: -30px;
    width: 110px;
    height: 110px;
    border-radius: 50%;
    background: currentColor;
    opacity: 0.05;
    pointer-events: none;
}

.summary-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 44px;
    height: 44px;
    flex: none;
    border-radius: 12px;
}

.summary-text {
    min-width: 0;
}

.summary-label {
    margin-bottom: 2px;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.4px;
    text-transform: uppercase;
    color: var(--mt-muted);
}

.summary-value {
    font-size: 26px;
    font-weight: 900;
    line-height: 1.15;
    color: var(--mt-purple-deep);
    overflow-wrap: anywhere;
}

.summary-1 { color: var(--mt-purple); }
.summary-1 .summary-icon { background: var(--mt-lavender); color: var(--mt-purple); }

.summary-2 { color: #4f46e5; }
.summary-2 .summary-icon { background: #eef0ff; color: #4f46e5; }

.summary-3 { color: var(--mt-success); }
.summary-3 .summary-icon { background: var(--mt-success-bg); color: var(--mt-success); }

.summary-4 { color: var(--mt-warn); }
.summary-4 .summary-icon { background: var(--mt-warn-bg); color: var(--mt-warn); }

/* ---------- Filters ---------- */

.filter-card {
    margin-bottom: 16px;
}

.filter-bar {
    display: flex;
    align-items: flex-end;
    flex-wrap: wrap;
    gap: 12px 14px;
    padding: 14px 16px;
}

.filter-field {
    display: flex;
    flex-direction: column;
    gap: 4px;
    flex: 1 1 170px;
    min-width: 0;
}

.filter-field.filter-search {
    flex: 2 1 240px;
}

.filter-label {
    margin: 0;
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    color: var(--mt-muted);
}

.inventory-dashboard-mt .form-control {
    height: 40px;
    border: 1px solid var(--mt-border);
    border-radius: 10px;
    background: var(--mt-white);
    color: var(--mt-text);
    font-size: 14px;
    box-shadow: none;
}

.inventory-dashboard-mt .form-control:focus {
    border-color: var(--mt-purple);
    box-shadow: 0 0 0 3px rgba(111, 45, 189, 0.15);
}

.input-icon {
    position: relative;
}

.input-icon svg {
    position: absolute;
    left: 12px;
    top: 50%;
    transform: translateY(-50%);
    color: var(--mt-muted);
    pointer-events: none;
}

.input-icon .form-control {
    padding-left: 34px;
}

.filter-toggles {
    display: flex;
    align-items: center;
    gap: 16px;
    height: 40px;
}

.mt-switch {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    margin: 0;
    cursor: pointer;
    user-select: none;
}

.mt-switch input {
    position: absolute;
    opacity: 0;
    width: 1px;
    height: 1px;
}

.mt-switch-track {
    position: relative;
    width: 38px;
    height: 22px;
    flex: none;
    border-radius: 999px;
    background: #d9cdee;
    transition: background 0.15s ease;
}

.mt-switch-track::after {
    content: "";
    position: absolute;
    top: 3px;
    left: 3px;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    background: var(--mt-white);
    box-shadow: 0 1px 3px rgba(43, 12, 87, 0.3);
    transition: transform 0.15s ease;
}

.mt-switch input:checked + .mt-switch-track {
    background: var(--mt-purple);
}

.mt-switch input:checked + .mt-switch-track::after {
    transform: translateX(16px);
}

.mt-switch input:focus-visible + .mt-switch-track {
    box-shadow: 0 0 0 3px rgba(111, 45, 189, 0.25);
}

.mt-switch-label {
    font-size: 13px;
    font-weight: 700;
    color: var(--mt-text);
    white-space: nowrap;
}

/* ---------- Table ---------- */

.table-card {
    overflow: hidden;
}

.table-wrapper {
    max-height: calc(100vh - var(--mt-navbar-offset) - 24px);
    overflow: auto;
    background: var(--mt-white);
}

.stock-table {
    width: 100%;
    min-width: 980px;
    margin: 0;
    border: 0;
    border-collapse: separate;
    border-spacing: 0;
}

.stock-table thead th {
    position: sticky;
    top: 0;
    z-index: 2;
    padding: 12px 14px;
    background: #f6f1ff;
    color: var(--mt-purple-dark);
    border: 0;
    border-bottom: 1px solid var(--mt-border-strong);
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.5px;
    text-transform: uppercase;
    white-space: nowrap;
    vertical-align: middle;
}

.stock-table tbody td {
    padding: 11px 14px;
    border: 0;
    border-bottom: 1px solid #f1eafc;
    font-size: 13px;
    vertical-align: middle;
    background: var(--mt-white);
    transition: background 0.12s ease;
}

.stock-table tbody tr:last-child td {
    border-bottom: 0;
}

.stock-table tbody tr:hover td {
    background: #fbf8ff;
}

.stock-table td.num {
    white-space: nowrap;
}

.stock-table tr.row-warning td {
    background: #fffcf2;
}

.stock-table tr.row-danger td {
    background: #fff7f8;
    color: #7a6a8f;
}

.stock-table tr.row-danger .item-name {
    color: #7a6a8f;
}

.item-code-cell {
    display: flex;
    align-items: center;
    gap: 6px;
    white-space: nowrap;
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
    font-size: 12px;
    color: var(--mt-muted);
}

.item-name {
    font-weight: 800;
    color: var(--mt-purple-deep);
}

.copy-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 26px;
    height: 26px;
    border: 1px solid transparent;
    border-radius: 8px;
    background: transparent;
    color: var(--mt-muted);
    cursor: pointer;
    opacity: 0.45;
    transition: opacity 0.15s ease, background 0.15s ease;
}

.stock-table tr:hover .copy-btn,
.copy-btn:focus-visible {
    opacity: 1;
}

.copy-btn:hover {
    background: var(--mt-lavender);
    color: var(--mt-purple);
}

/* Badges */
.status-badge,
.type-badge,
.yield-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    border-radius: 999px;
    font-size: 11px;
    font-weight: 800;
    white-space: nowrap;
}

.status-badge::before {
    content: "";
    width: 7px;
    height: 7px;
    border-radius: 50%;
    background: currentColor;
}

.status-good {
    background: var(--mt-success-bg);
    color: var(--mt-success);
}

.status-low {
    background: var(--mt-warn-bg);
    color: var(--mt-warn);
}

.status-out {
    background: var(--mt-danger-bg);
    color: var(--mt-danger);
}

.type-bho {
    background: var(--mt-lavender);
    color: #5a2396;
}

.type-sho {
    background: #fff4c4;
    color: #7b5600;
}

.yield-badge {
    background: #f4f0ff;
    color: var(--mt-purple-dark);
}

.yield-badge-rosin {
    background: #fff8e6;
    color: #7b5600;
}

/* States */
.empty-state,
.loading-state {
    padding: 56px 16px;
    text-align: center;
    color: var(--mt-muted);
    font-weight: 700;
}

.loading-state::before {
    content: "";
    display: block;
    width: 28px;
    height: 28px;
    margin: 0 auto 12px;
    border: 3px solid var(--mt-lavender);
    border-top-color: var(--mt-purple);
    border-radius: 50%;
    animation: mt-spin 0.8s linear infinite;
}

@keyframes mt-spin {
    to { transform: rotate(360deg); }
}

/* ---------- Responsive ---------- */

@media (max-width: 1199px) {
    .mt-layout {
        grid-template-columns: 1fr;
    }

    .sidebar-card {
        position: static;
    }

    .sidebar-header {
        cursor: pointer;
    }

    .toggle-icon {
        display: inline;
    }

    .sidebar-body {
        max-height: none;
    }

    .group-list-container {
        display: grid;
        grid-template-columns: repeat(auto-fill, minmax(170px, 1fr));
    }

    .summary-grid {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}

@media (max-width: 767px) {
    .mt-shell {
        padding: 16px 16px 96px;
    }

    .dashboard-title {
        font-size: 22px;
    }

    .mt-brand-mark {
        width: 40px;
        height: 40px;
    }

    .selected-group-text {
        font-size: 20px;
    }

    .summary-card {
        padding: 14px;
    }

    .summary-icon {
        width: 36px;
        height: 36px;
    }

    .summary-value {
        font-size: 20px;
    }

    .filter-toggles {
        height: auto;
        flex-wrap: wrap;
    }

    .mt-reset-btn {
        flex: 1 1 100%;
    }

    .table-wrapper {
        max-height: 70vh;
    }
}

@media (prefers-reduced-motion: reduce) {
    .loading-state::before {
        animation-duration: 2s;
    }
}

/* ---------- Order cart ---------- */

.header-right {
    display: flex;
    align-items: center;
    gap: 10px;
}

.mt-order-btn[hidden],
.mt-order-float[hidden],
.mt-modal-backdrop[hidden],
.mt-modal-content[hidden],
.mt-modal-footer[hidden],
.mt-modal-success[hidden],
.of-field[hidden],
.order-banner[hidden],
.order-error[hidden],
.ol-warn[hidden] {
    display: none !important;
}

/* Header button */
.mt-order-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: 0;
    border-radius: 999px;
    padding: 10px 16px 10px 18px;
    font-weight: 800;
    background: linear-gradient(135deg, var(--mt-purple) 0%, var(--mt-purple-dark) 100%);
    color: var(--mt-white);
    box-shadow: var(--mt-shadow-strong);
    transition: transform 0.15s ease, box-shadow 0.15s ease;
}

.mt-order-btn:hover,
.mt-order-btn:focus-visible {
    color: var(--mt-gold);
    transform: translateY(-1px);
}

.order-count-badge {
    min-width: 26px;
    padding: 2px 8px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.18);
    color: var(--mt-white);
    font-size: 12px;
    text-align: center;
}

.mt-order-btn.has-items .order-count-badge {
    background: var(--mt-gold);
    color: var(--mt-purple-deep);
}

/* Row checkboxes */
.order-check-col {
    width: 44px;
    text-align: center;
    vertical-align: middle;
}

.order-check {
    width: 18px;
    height: 18px;
    cursor: pointer;
    accent-color: var(--mt-purple);
    vertical-align: middle;
}

.stock-table tr.row-selected td {
    background: var(--mt-lavender) !important;
}

.stock-table tr.row-selected td:first-child {
    box-shadow: inset 4px 0 0 var(--mt-purple);
}

/* Floating "View Order" bar */
.mt-order-float {
    position: fixed;
    right: 24px;
    bottom: 24px;
    z-index: 1045;
    display: inline-flex;
    align-items: center;
    gap: 12px;
    max-width: calc(100vw - 32px);
    padding: 10px 10px 10px 16px;
    border: 0;
    border-radius: 999px;
    background: var(--mt-purple-deep);
    color: var(--mt-white);
    font-weight: 800;
    box-shadow: 0 18px 40px rgba(43, 12, 87, 0.35);
    cursor: pointer;
    animation: mt-rise 0.2s ease-out;
}

.mt-order-float-icon {
    display: inline-flex;
    color: var(--mt-gold);
}

.mt-order-float-cta {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 14px;
    border-radius: 999px;
    background: var(--mt-gold);
    color: var(--mt-purple-deep);
}

.mt-order-float:hover .mt-order-float-cta {
    background: var(--mt-gold-deep);
}

/* Modal shell */
body.mt-modal-open {
    overflow: hidden;
}

/* Error dialogs (frappe.msgprint), the save freeze and toasts must still show
   on top of the popup while it is open. */
body.mt-modal-open .modal {
    z-index: 1080 !important;
}

body.mt-modal-open .modal-backdrop {
    z-index: 1070 !important;
}

body.mt-modal-open #alert-container {
    z-index: 1090 !important;
}

.mt-modal-backdrop {
    position: fixed;
    inset: 0;
    /* Above the theme's navbar (z-index 1050 !important). */
    z-index: 1060;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px 16px;
    background: rgba(43, 12, 87, 0.5);
    backdrop-filter: blur(3px);
    animation: mt-fade 0.15s ease-out;
}

.mt-modal {
    display: flex;
    flex-direction: column;
    width: 100%;
    max-width: 1120px;
    max-height: calc(100vh - 48px);
    background: #fcfaff;
    color: var(--mt-text);
    border-radius: 22px;
    box-shadow: 0 30px 70px rgba(43, 12, 87, 0.35);
    overflow: hidden;
    animation: mt-pop 0.18s ease-out;
}

.mt-modal-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 12px;
    padding: 18px 22px;
    background: linear-gradient(135deg, var(--mt-purple-deep) 0%, var(--mt-purple) 100%);
    color: var(--mt-white);
}

.mt-modal-heading {
    display: flex;
    align-items: center;
    gap: 12px;
    min-width: 0;
}

.mt-modal-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: 12px;
    background: rgba(255, 216, 77, 0.16);
    color: var(--mt-gold);
    flex: none;
}

.mt-modal-header h4 {
    margin: 0;
    font-size: 20px;
    font-weight: 900;
    color: var(--mt-white);
}

.mt-modal-sub {
    font-size: 13px;
    color: rgba(255, 255, 255, 0.75);
}

.mt-modal-header-actions {
    display: flex;
    align-items: center;
    gap: 10px;
}

.mt-draft-pill {
    padding: 4px 10px;
    border-radius: 999px;
    background: rgba(255, 255, 255, 0.14);
    border: 1px solid rgba(255, 255, 255, 0.25);
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.3px;
    text-transform: uppercase;
}

.mt-modal-close {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 36px;
    height: 36px;
    border: 0;
    border-radius: 10px;
    background: transparent;
    color: var(--mt-white);
    cursor: pointer;
}

.mt-modal-close:hover,
.mt-modal-close:focus-visible {
    background: rgba(255, 255, 255, 0.14);
}

.mt-modal-content {
    display: grid;
    grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr);
    flex: 1;
    min-height: 0;
    overflow: hidden;
}

.order-pane {
    min-height: 0;
    overflow-y: auto;
    padding: 18px 22px 22px;
}

.order-pane-details {
    background: var(--mt-white);
    border-left: 1px solid var(--mt-border);
}

.order-pane-head {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 12px;
}

.order-pane-head h5 {
    margin: 0;
    font-size: 15px;
    font-weight: 900;
    color: var(--mt-purple-dark);
}

.mt-link-btn {
    border: 0;
    background: none;
    padding: 4px 6px;
    font-size: 13px;
    font-weight: 800;
    color: #b42318;
    cursor: pointer;
    border-radius: 8px;
}

.mt-link-btn:hover,
.mt-link-btn:focus-visible {
    background: #fdecea;
}

/* Info banner */
.order-banner {
    display: flex;
    gap: 10px;
    align-items: flex-start;
    margin-bottom: 12px;
    padding: 10px 12px;
    border-radius: 12px;
    background: #fff8dd;
    border: 1px solid var(--mt-gold-deep);
    color: var(--mt-purple-deep);
    font-size: 13px;
}

.order-banner svg {
    flex: none;
    margin-top: 1px;
    color: #a16207;
}

/* Item cards */
.order-lines {
    display: flex;
    flex-direction: column;
    gap: 10px;
}

.ol-card {
    display: grid;
    grid-template-columns: minmax(0, 1fr) auto;
    gap: 6px 14px;
    padding: 12px 14px;
    border: 1px solid var(--mt-border);
    border-radius: 14px;
    background: var(--mt-white);
    box-shadow: 0 4px 12px rgba(111, 45, 189, 0.05);
}

.ol-card.is-over {
    border-color: #f0b44c;
    background: #fffaf0;
}

.ol-name {
    font-weight: 800;
    font-size: 15px;
    color: var(--mt-purple-deep);
    overflow-wrap: anywhere;
}

.ol-meta {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 6px;
    margin-top: 3px;
}

.ol-code {
    font-size: 12px;
    color: var(--mt-muted);
    font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
}

.ol-chip {
    padding: 1px 8px;
    border-radius: 999px;
    background: var(--mt-lavender);
    color: var(--mt-purple-dark);
    font-size: 11px;
    font-weight: 800;
}

.ol-stock {
    margin-top: 4px;
    font-size: 12px;
    color: var(--mt-muted);
}

.ol-stock strong {
    color: var(--mt-text);
}

.ol-inputs {
    display: flex;
    align-items: flex-end;
    gap: 8px;
}

.ol-input {
    display: flex;
    flex-direction: column;
    gap: 3px;
    margin: 0;
}

.ol-input span {
    font-size: 11px;
    font-weight: 800;
    color: var(--mt-muted);
    text-transform: uppercase;
    letter-spacing: 0.3px;
}

.ol-input .form-control {
    width: 104px;
    height: 38px;
    text-align: right;
    font-weight: 700;
    border-radius: 10px;
}

.ol-remove {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 38px;
    height: 38px;
    border: 1px solid transparent;
    border-radius: 10px;
    background: transparent;
    color: #b42318;
    cursor: pointer;
}

.ol-remove:hover,
.ol-remove:focus-visible {
    background: #fdecea;
    border-color: #f5b5ad;
}

.ol-warn {
    grid-column: 1 / -1;
    font-size: 12px;
    font-weight: 700;
    color: #a16207;
}

.order-empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 36px 16px;
    border: 2px dashed var(--mt-border);
    border-radius: 16px;
    text-align: center;
    color: var(--mt-muted);
}

.order-empty-icon {
    color: var(--mt-purple);
    opacity: 0.6;
}

.order-empty strong {
    color: var(--mt-purple-dark);
}

/* Details form */
.of-group + .of-group {
    margin-top: 16px;
    padding-top: 16px;
    border-top: 1px dashed var(--mt-border);
}

.of-group-title {
    margin-bottom: 8px;
    font-size: 11px;
    font-weight: 900;
    letter-spacing: 0.6px;
    text-transform: uppercase;
    color: var(--mt-purple);
}

.of-grid {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 10px 12px;
}

.of-field.of-wide {
    grid-column: 1 / -1;
}

.of-field label {
    display: block;
    margin-bottom: 4px;
    font-size: 12px;
    font-weight: 800;
    color: var(--mt-muted);
}

.of-control {
    border-radius: 10px;
    border-color: var(--mt-border);
    min-height: 40px;
}

.of-control:focus,
.ol-input .form-control:focus {
    border-color: var(--mt-purple);
    box-shadow: 0 0 0 3px rgba(111, 45, 189, 0.18);
}

.of-control.is-invalid,
.ol-input .form-control.is-invalid {
    border-color: #d92d20;
    box-shadow: 0 0 0 3px rgba(217, 45, 32, 0.15);
}

.of-reqd {
    color: #b42318;
}

/* Footer */
.mt-modal-footer {
    display: flex;
    align-items: center;
    flex-wrap: wrap;
    gap: 10px;
    padding: 14px 22px;
    border-top: 1px solid var(--mt-border);
    background: var(--mt-white);
}

.mt-modal-hint {
    font-size: 12px;
    color: var(--mt-muted);
}

.mt-modal-spacer {
    flex: 1;
}

.mt-cancel-btn {
    border-radius: 12px;
    font-weight: 800;
    padding: 10px 16px;
    background: var(--mt-white);
    border: 1px solid var(--mt-border);
    color: var(--mt-purple-dark);
}

.mt-cancel-btn:hover {
    background: var(--mt-lavender-2);
    color: var(--mt-purple-dark);
}

.mt-save-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    border: 0;
    border-radius: 12px;
    font-weight: 900;
    padding: 10px 18px;
    background: linear-gradient(135deg, var(--mt-purple) 0%, var(--mt-purple-dark) 100%);
    color: var(--mt-gold);
    box-shadow: 0 8px 18px rgba(75, 29, 143, 0.25);
}

.mt-save-btn:hover,
.mt-save-btn:focus-visible {
    color: var(--mt-white);
}

.mt-save-btn:disabled {
    opacity: 0.6;
}

.order-error {
    flex-basis: 100%;
    padding: 10px 12px;
    border-radius: 12px;
    background: #fdecea;
    border: 1px solid #f5b5ad;
    color: #8a1c12;
    font-weight: 700;
}

/* Success view */
.mt-modal-success {
    display: flex;
    flex-direction: column;
    align-items: center;
    padding: 36px 22px 30px;
    text-align: center;
    overflow-y: auto;
}

.order-success-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 72px;
    height: 72px;
    border-radius: 50%;
    background: #e8f7ee;
    color: #15803d;
    box-shadow: 0 0 0 8px #f3fbf6;
    margin-bottom: 14px;
    animation: mt-pop 0.25s ease-out;
}

.mt-modal-success h4 {
    margin: 0 0 4px;
    font-weight: 900;
    color: var(--mt-purple-deep);
}

.mt-modal-success p {
    margin: 0 0 18px;
    color: var(--mt-muted);
}

.order-success-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
    width: 100%;
    max-width: 480px;
}

.order-success-card {
    display: grid;
    grid-template-columns: 1fr auto;
    grid-template-areas: "name open" "meta open";
    gap: 2px 12px;
    align-items: center;
    padding: 12px 16px;
    border: 1px solid var(--mt-border);
    border-radius: 14px;
    background: var(--mt-white);
    text-align: left;
    text-decoration: none !important;
    transition: border-color 0.15s ease, transform 0.15s ease;
}

.order-success-card:hover,
.order-success-card:focus-visible {
    border-color: var(--mt-purple);
    transform: translateY(-1px);
}

.order-success-name {
    grid-area: name;
    font-weight: 900;
    color: var(--mt-purple-dark);
}

.order-success-meta {
    grid-area: meta;
    font-size: 12px;
    color: var(--mt-muted);
}

.order-success-open {
    grid-area: open;
    display: inline-flex;
    align-items: center;
    gap: 6px;
    font-size: 13px;
    font-weight: 800;
    color: var(--mt-purple);
}

.order-success-actions {
    display: flex;
    gap: 10px;
    margin-top: 22px;
}

@keyframes mt-fade {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes mt-pop {
    from { opacity: 0; transform: translateY(8px) scale(0.98); }
    to { opacity: 1; transform: none; }
}

@keyframes mt-rise {
    from { opacity: 0; transform: translateY(12px); }
    to { opacity: 1; transform: none; }
}

@media (prefers-reduced-motion: reduce) {
    .mt-modal,
    .mt-modal-backdrop,
    .mt-order-float,
    .order-success-badge {
        animation: none;
    }
}

@media (max-width: 900px) {
    .mt-modal-content {
        grid-template-columns: 1fr;
        overflow-y: auto;
    }

    .order-pane {
        overflow: visible;
    }

    .order-pane-details {
        border-left: 0;
        border-top: 1px solid var(--mt-border);
    }
}

@media (max-width: 640px) {
    .mt-modal-backdrop {
        padding: 0;
        align-items: stretch;
    }

    .mt-modal {
        max-height: none;
        height: 100%;
        border-radius: 0;
    }

    .mt-modal-header,
    .order-pane,
    .mt-modal-footer {
        padding-left: 16px;
        padding-right: 16px;
    }

    .mt-draft-pill,
    .mt-modal-hint {
        display: none;
    }

    .ol-card {
        grid-template-columns: 1fr;
    }

    .ol-inputs {
        justify-content: flex-start;
    }

    .ol-input .form-control {
        width: 96px;
    }

    .of-grid {
        grid-template-columns: 1fr;
    }

    .header-right,
    .mt-order-btn {
        width: 100%;
        justify-content: center;
    }

    .mt-order-float {
        right: 16px;
        bottom: 16px;
        left: 16px;
        justify-content: space-between;
    }

    .mt-modal-footer .btn {
        flex: 1;
        justify-content: center;
    }
}

/* ---------- Access code lock ---------- */

.mt-modal {
    position: relative;
}

.mt-modal.is-locked > :not(.order-lock) {
    filter: blur(6px);
    pointer-events: none;
    user-select: none;
}

.order-lock[hidden],
.order-lock-error[hidden],
.order-totals[hidden] {
    display: none !important;
}

.order-lock {
    position: absolute;
    inset: 0;
    z-index: 5;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px 16px;
    background: rgba(247, 242, 255, 0.55);
}

.order-lock-card {
    display: flex;
    flex-direction: column;
    align-items: center;
    width: 100%;
    max-width: 360px;
    padding: 28px 24px 22px;
    border: 1px solid var(--mt-border);
    border-radius: 20px;
    background: var(--mt-white);
    box-shadow: 0 24px 60px rgba(43, 12, 87, 0.28);
    text-align: center;
    animation: mt-pop 0.18s ease-out;
}

.order-lock-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 56px;
    height: 56px;
    margin-bottom: 12px;
    border-radius: 16px;
    background: linear-gradient(135deg, var(--mt-purple) 0%, var(--mt-purple-deep) 100%);
    color: var(--mt-gold);
}

.order-lock-card h5 {
    margin: 0 0 4px;
    font-weight: 900;
    color: var(--mt-purple-deep);
}

.order-lock-card p {
    margin: 0 0 16px;
    font-size: 13px;
    color: var(--mt-muted);
}

.order-lock-input {
    height: 48px;
    border-radius: 12px;
    border-color: var(--mt-border);
    text-align: center;
    font-size: 22px;
    font-weight: 800;
    letter-spacing: 6px;
}

.order-lock-input:focus {
    border-color: var(--mt-purple);
    box-shadow: 0 0 0 3px rgba(111, 45, 189, 0.18);
}

.order-lock-error {
    width: 100%;
    margin-top: 10px;
    padding: 8px 10px;
    border-radius: 10px;
    background: var(--mt-danger-bg);
    color: var(--mt-danger);
    font-size: 13px;
    font-weight: 700;
}

.order-lock-actions {
    display: flex;
    gap: 10px;
    width: 100%;
    margin-top: 16px;
}

.order-lock-actions .btn {
    flex: 1;
    justify-content: center;
}

.order-lock-card.shake {
    animation: mt-shake 0.35s ease-in-out;
}

@keyframes mt-shake {
    0%, 100% { transform: translateX(0); }
    20% { transform: translateX(-8px); }
    40% { transform: translateX(8px); }
    60% { transform: translateX(-5px); }
    80% { transform: translateX(5px); }
}

/* ---------- Rate currency, line subtotal, totals ---------- */

.ol-money {
    position: relative;
    display: block;
}

.ol-currency {
    position: absolute;
    left: 10px;
    top: 50%;
    transform: translateY(-50%);
    font-size: 13px;
    font-weight: 800;
    color: var(--mt-muted);
    pointer-events: none;
}

.ol-money .form-control.ol-rate {
    width: 120px;
    padding-left: 24px;
}

.ol-subtotal {
    grid-column: 1 / -1;
    padding-top: 8px;
    border-top: 1px dashed var(--mt-border);
    text-align: right;
    font-size: 13px;
    color: var(--mt-muted);
}

.ol-subtotal strong {
    margin-left: 6px;
    font-size: 15px;
    color: var(--mt-purple-deep);
}

.order-totals {
    position: sticky;
    bottom: 0;
    margin: 14px -22px -22px;
    padding: 14px 22px 16px;
    border-top: 1px solid var(--mt-border);
    background: linear-gradient(180deg, rgba(252, 250, 255, 0.92) 0%, #f7f2ff 100%);
    backdrop-filter: blur(4px);
}

.ot-row {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 12px;
    padding: 3px 0;
    font-size: 14px;
    color: var(--mt-muted);
}

.ot-row strong {
    color: var(--mt-text);
    font-weight: 800;
}

.ot-row.ot-total {
    margin-top: 6px;
    padding-top: 8px;
    border-top: 1px solid var(--mt-border);
    font-size: 16px;
    font-weight: 900;
    color: var(--mt-purple-deep);
}

.ot-row.ot-total strong {
    font-size: 20px;
    color: var(--mt-purple-deep);
}

.ot-note {
    margin-top: 6px;
    font-size: 12px;
    color: var(--mt-muted);
}

.warehouse-cell {
    white-space: nowrap;
}

@media (max-width: 900px) {
    .order-totals {
        position: static;
        margin: 14px 0 0;
        padding: 14px 0 0;
        background: none;
        backdrop-filter: none;
    }
}

@media (prefers-reduced-motion: reduce) {
    .order-lock-card,
    .order-lock-card.shake {
        animation: none;
    }
}

javascript:
frappe.ready(function () {
    bindGlobalFilters();
    bindSidebarToggle();
    bindExportButton();
    bindGroupSearch();
    initOrderCart();
    loadItemGroups();
});

// ---------------------------------------------------
// CONFIG
// ---------------------------------------------------

const GROUP_ORDER = [
    'Fresh Frozen',
    'Tier 1 Plus',
    'Tier 1',
    'Tier 2',
    'Tier 3',
    'Primes',
    'Subprimes',
    'VRR',
    'O2 Vape',
    '1g O2 Vapes',
    'LIQUID LIVE RESIN',
    'Full Spec',
    'Food Grade',
    'Gummies',
    'Farm Supplies',
    'Drawings'
];

const DEFAULT_WAREHOUSE = "Main Storage - MTM";
const GROUP_DEFAULT_WAREHOUSE = {
    'Fresh Frozen':  'Hemet TSBC - TSBC',
    'Tier 1 Plus':        'Main Storage - MTM',
    'Tier 1':        'Main Storage - MTM',
    'Tier 2':        'Main Storage - MTM',
    'Tier 3':        'Main Storage - MTM',
    'Primes':        'Main Storage - MTM',
    '0.5g O2 Vape':  'Conversion - MTM',
};

const LOW_STOCK_THRESHOLD = 5;

const FRESH_FROZEN_MAIN_GROUP = 'Fresh Frozen';
const FRESH_FROZEN_SUBGROUPS = [
    'Fresh Frozen',
    'Fresh Frozen - BHO',
    'Fresh Frozen - SHO'
];

// ---------------------------------------------------
// STATE
// ---------------------------------------------------

let CURRENT_GROUP = null;
let CURRENT_ITEMS = [];
let CURRENT_FILTERED_ITEMS = [];
let CURRENT_HAS_WAREHOUSE = false;

let GROUP_PROJECTS = []; // the group's projects with stock showing, each with its warehouses
let PROJECT_LABELS = {}; // project name -> project_name, as last listed

let FILTERS = {
    project: '__ALL__',
    warehouse: '__ALL__',
    search: '',
    onlyAvailable: false,
    lowStockOnly: false
};

// ---------------------------------------------------
// HELPERS
// ---------------------------------------------------

function getDefaultWarehouse(group) {
    return GROUP_DEFAULT_WAREHOUSE[group] || DEFAULT_WAREHOUSE;
}

function isFreshFrozenCombinedView(group) {
    return group === FRESH_FROZEN_MAIN_GROUP;
}

function getLoadGroups(group) {
    if (isFreshFrozenCombinedView(group)) {
        return FRESH_FROZEN_SUBGROUPS.slice();
    }
    return [group];
}

function getTypeLabel(item) {
    const itemGroup = String(item.item_group || '').trim();

    if (itemGroup === 'Fresh Frozen - BHO') return 'BHO';
    if (itemGroup === 'Fresh Frozen - SHO') return 'SHO';
    return '';
}

function getTypeClass(typeLabel) {
    if (typeLabel === 'BHO') return 'type-badge type-bho';
    if (typeLabel === 'SHO') return 'type-badge type-sho';
    return '';
}

function escapeRegex(string) {
    return String(string).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function escapeHtml(str) {
    if (str === null || str === undefined) return '';
    return String(str)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;');
}

function cleanItemName(itemName, itemGroup) {
    if (!itemName) return '-';

    let name = String(itemName);

    if (itemGroup) {
        let groupSuffix = new RegExp('\\s*[-]\\s*' + escapeRegex(itemGroup) + '$', 'i');
        name = name.replace(groupSuffix, '');
    }

    if (itemGroup) {
        let underscoreGroupPattern = new RegExp('[_][A-Za-z0-9][-]' + escapeRegex(itemGroup) + '$', 'i');
        name = name.replace(underscoreGroupPattern, '');
    }

    name = name.replace(/_CDC$/i, '');
    name = name.replace(/_[A-Za-z0-9]$/i, '');
    name = name.replace(/_/g, ' ');
    name = name.trim();

    return name || String(itemName);
}

// 55854.49 -> "55,854.49" for display; CSV export keeps plain numbers.
function fmtQty(val) {
    return parseNum(val).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

function parseNum(val) {
    let n = parseFloat(val || 0);
    return isNaN(n) ? 0 : n;
}

function getAvailable(item) {
    return parseNum(item.actual_qty) - parseNum(item.reserved_qty);
}

function getStatusClass(available) {
    if (available <= 0) return 'status-out';
    if (available <= LOW_STOCK_THRESHOLD) return 'status-low';
    return 'status-good';
}

function getStatusLabel(available) {
    if (available <= 0) return 'Out of Stock';
    if (available <= LOW_STOCK_THRESHOLD) return 'Low Stock';
    return 'Available';
}

function debounce(fn, delay) {
    let timer = null;
    return function () {
        const context = this;
        const args = arguments;
        clearTimeout(timer);
        timer = setTimeout(function () {
            fn.apply(context, args);
        }, delay);
    };
}

function decodeHtmlEntities(str) {
    const txt = document.createElement('textarea');
    txt.innerHTML = str;
    return txt.value;
}

function deduplicateItems(items) {
    const seen = {};
    const output = [];

    items.forEach(function (item) {
        const key = [
            String(item.item_code || '').trim(),
            String(item.warehouse || '').trim(),
            String(item.item_group || '').trim()
        ].join('||');

        if (!seen[key]) {
            seen[key] = true;
            output.push(item);
        }
    });

    return output;
}

function csvEscape(value) {
    if (value === null || value === undefined) return '';
    const str = String(value);
    return '"' + str.replace(/"/g, '""') + '"';
}

// ---------------------------------------------------
// BINDINGS
// ---------------------------------------------------

function bindGlobalFilters() {
    const searchEl = document.getElementById('search-box');
    const warehouseEl = document.getElementById('warehouse-filter');
    const projectEl = document.getElementById('project-filter');
    const onlyAvailableEl = document.getElementById('only-available');
    const lowStockOnlyEl = document.getElementById('low-stock-only');
    const resetBtn = document.getElementById('reset-filters-btn');

    // A project's stock comes from the ledger, not Bin, so picking one
    // reloads the group (keeping the other filters as they are).
    if (projectEl) {
        projectEl.addEventListener('change', function () {
            FILTERS.project = this.value;
            if (CURRENT_GROUP) loadStock(CURRENT_GROUP, true);
        });
    }

    if (searchEl) {
        searchEl.addEventListener('input', debounce(function () {
            FILTERS.search = this.value.trim().toLowerCase();
            renderWithFilters();
        }, 200));
    }

    if (warehouseEl) {
        warehouseEl.addEventListener('change', function () {
            FILTERS.warehouse = this.value;
            renderWithFilters();
        });
    }

    if (onlyAvailableEl) {
        onlyAvailableEl.addEventListener('change', function () {
            FILTERS.onlyAvailable = this.checked;
            renderWithFilters();
        });
    }

    if (lowStockOnlyEl) {
        lowStockOnlyEl.addEventListener('change', function () {
            FILTERS.lowStockOnly = this.checked;
            renderWithFilters();
        });
    }

    if (resetBtn) {
        resetBtn.addEventListener('click', function () {
            const hadProject = FILTERS.project !== '__ALL__';
            resetFiltersToDefault();
            if (hadProject && CURRENT_GROUP) loadStock(CURRENT_GROUP, true);
            else renderWithFilters();
        });
    }
}

function bindGroupSearch() {
    const input = document.getElementById('group-search');
    if (input) input.addEventListener('input', filterGroupList);
}

function filterGroupList() {
    const input = document.getElementById('group-search');
    const term = input ? input.value.trim().toLowerCase() : '';
    let shown = 0;
    document.querySelectorAll('#group-list .item-group-btn').forEach(function (btn) {
        const match = !term || btn.textContent.toLowerCase().includes(term);
        btn.hidden = !match;
        if (match) shown++;
    });
    const empty = document.querySelector('#group-list .group-empty');
    if (empty) empty.hidden = shown > 0;
}

function bindSidebarToggle() {
    const toggle = document.getElementById('sidebar-toggle');
    if (!toggle) return;

    toggle.addEventListener('click', function () {
        if (window.innerWidth < 1200) {
            const sidebar = document.querySelector('.sidebar-body');
            const icon = document.querySelector('.toggle-icon');
            if (sidebar) {
                sidebar.classList.toggle('collapsed');
                if (icon) {
                    icon.innerText = sidebar.classList.contains('collapsed') ? '▼' : '▲';
                }
            }
        }
    });
}

function bindExportButton() {
    const exportBtn = document.getElementById('export-csv-btn');
    if (!exportBtn) return;

    exportBtn.addEventListener('click', function () {
        exportCurrentViewToCSV();
    });
}

function resetFiltersToDefault() {
    FILTERS.search = '';
    FILTERS.onlyAvailable = false;
    FILTERS.lowStockOnly = false;
    FILTERS.warehouse = CURRENT_GROUP ? getDefaultWarehouse(CURRENT_GROUP) : '__ALL__';
    FILTERS.project = '__ALL__';

    const projectEl = document.getElementById('project-filter');
    if (projectEl) projectEl.value = '__ALL__';

    const searchEl = document.getElementById('search-box');
    const warehouseEl = document.getElementById('warehouse-filter');
    const onlyAvailableEl = document.getElementById('only-available');
    const lowStockOnlyEl = document.getElementById('low-stock-only');

    if (searchEl) searchEl.value = '';
    if (onlyAvailableEl) onlyAvailableEl.checked = false;
    if (lowStockOnlyEl) lowStockOnlyEl.checked = false;
    if (warehouseEl) warehouseEl.value = FILTERS.warehouse;
}

// ---------------------------------------------------
// GROUPS
// ---------------------------------------------------

function loadItemGroups() {
    frappe.call({
        method: 'cannabis_management.api.inventory_dashboard2.get_item_groups',
        callback: function (r) {
            if (r && r.message && Array.isArray(r.message)) {
                const cleanedGroups = hideFreshFrozenSubgroups(r.message);
                renderItemGroups(sortItemGroups(cleanedGroups));
                restoreSavedGroup(cleanedGroups);
            } else {
                document.getElementById('group-list').innerHTML =
                    '<div class="empty-state">No item groups found</div>';
            }
        },
        error: function () {
            document.getElementById('group-list').innerHTML =
                '<div class="empty-state">Could not load item groups</div>';
        }
    });
}

function hideFreshFrozenSubgroups(groups) {
    return groups.filter(function (group) {
        const name = String(group.name || '').trim();
        return name !== 'Fresh Frozen - BHO' && name !== 'Fresh Frozen - SHO';
    });
}

function sortItemGroups(groups) {
    return groups.sort(function (a, b) {
        const idxA = GROUP_ORDER.findIndex(function (g) {
            return g.toLowerCase() === String(a.name).toLowerCase();
        });

        const idxB = GROUP_ORDER.findIndex(function (g) {
            return g.toLowerCase() === String(b.name).toLowerCase();
        });

        if (idxA !== -1 && idxB !== -1) return idxA - idxB;
        if (idxA !== -1) return -1;
        if (idxB !== -1) return 1;
        return String(a.name).localeCompare(String(b.name));
    });
}

function renderItemGroups(groups) {
    let html = '<div class="group-list-container">';

    groups.forEach(function (group) {
        html += `
            <button type="button" class="item-group-btn" data-group="${escapeHtml(group.name)}">
                <span class="ig-name">${escapeHtml(group.name)}</span>
                <svg class="ig-chevron" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m9 6 6 6-6 6"/></svg>
            </button>
        `;
    });

    html += '<div class="group-empty" hidden>No groups match</div>';

    html += '</div>';

    const container = document.getElementById('group-list');
    container.innerHTML = html;
    filterGroupList();

    container.querySelectorAll('.item-group-btn').forEach(function (btn) {
        btn.addEventListener('click', function () {
            const groupName = decodeHtmlEntities(this.getAttribute('data-group'));
            loadStock(groupName);
        });
    });
}

// ---------------------------------------------------
// LOAD STOCK
// ---------------------------------------------------

function loadStock(itemGroup, keepFilters) {
    CURRENT_GROUP = itemGroup;
    saveGroup(itemGroup);
    CURRENT_ITEMS = [];
    CURRENT_FILTERED_ITEMS = [];
    CURRENT_HAS_WAREHOUSE = false;

    document.getElementById('selected-group').innerText = itemGroup + projectHeadingSuffix();
    document.getElementById('stock-table').innerHTML =
        '<div class="loading-state">Loading stock...</div>';

    document.querySelectorAll('.item-group-btn').forEach(function (el) {
        el.classList.remove('active');
        if (decodeHtmlEntities(el.getAttribute('data-group')) === itemGroup) {
            el.classList.add('active');
        }
    });

    const groupsToLoad = getLoadGroups(itemGroup);
    let pending = groupsToLoad.length;
    let combinedItems = [];
    let combinedProjects = [];
    let hasError = false;

    groupsToLoad.forEach(function (groupName) {
        frappe.call({
            method: 'cannabis_management.api.inventory_dashboard.get_stock_by_item_group',
            args: {
                item_group: groupName,
                project: FILTERS.project !== '__ALL__' ? FILTERS.project : null,
                _: Date.now()
            },
            callback: function (r) {
                let items = [];

                if (r && r.message) {
                    if (Array.isArray(r.message)) {
                        items = r.message;
                    } else if (Array.isArray(r.message.items)) {
                        items = r.message.items;
                    }
                }

                items = items.map(function (item) {
                    if (!item.item_group) {
                        item.item_group = groupName;
                    }
                    return item;
                });

                combinedItems = combinedItems.concat(items);
                if (r && r.message && Array.isArray(r.message.projects)) {
                    combinedProjects = combinedProjects.concat(r.message.projects);
                }
                pending--;

                if (pending === 0) {
                    finalizeStockLoad(itemGroup, combinedItems, hasError, keepFilters, combinedProjects);
                }
            },
            error: function () {
                hasError = true;
                pending--;

                if (pending === 0) {
                    finalizeStockLoad(itemGroup, combinedItems, hasError, keepFilters, combinedProjects);
                }
            }
        });
    });
}

function finalizeStockLoad(itemGroup, items, hasError, keepFilters, projects) {
    CURRENT_ITEMS = deduplicateItems(items || []);

    CURRENT_HAS_WAREHOUSE = CURRENT_ITEMS.some(function (i) {
        return i && i.warehouse;
    });

    setGroupProjects(projects || []);

    if (keepFilters && !(hasError && !CURRENT_ITEMS.length)) {
        renderWithFilters();
        return;
    }

    FILTERS.search = '';
    FILTERS.onlyAvailable = false;
    FILTERS.lowStockOnly = false;
    FILTERS.warehouse = getDefaultWarehouse(itemGroup);

    const searchEl = document.getElementById('search-box');
    const onlyAvailableEl = document.getElementById('only-available');
    const lowStockOnlyEl = document.getElementById('low-stock-only');

    if (searchEl) searchEl.value = '';
    if (onlyAvailableEl) onlyAvailableEl.checked = false;
    if (lowStockOnlyEl) lowStockOnlyEl.checked = false;

    if (hasError && !CURRENT_ITEMS.length) {
        renderSummary([]);
        populateWarehouseDropdown([]);
        document.getElementById('stock-table').innerHTML =
            '<div class="empty-state">Could not load stock items</div>';
        return;
    }

    renderWithFilters();
}

// ---------------------------------------------------
// FILTERS + RENDER
// ---------------------------------------------------

function renderWithFilters() {
    if (!CURRENT_ITEMS || !CURRENT_ITEMS.length) {
        CURRENT_FILTERED_ITEMS = [];
        renderSummary([]);
        populateWarehouseDropdown([]);
        renderProjectOptions();
        document.getElementById('stock-table').innerHTML =
            '<div class="empty-state">No items found for this group</div>';
        return;
    }

    if (!CURRENT_HAS_WAREHOUSE) {
        CURRENT_FILTERED_ITEMS = [];
        renderSummary([]);
        populateWarehouseDropdown([]);
        document.getElementById('stock-table').innerHTML = `
            <div class="alert alert-danger mb-0">
                Warehouse field is missing from the API response. Front end warehouse filtering cannot work until warehouse is included in the backend response.
            </div>
        `;
        return;
    }

    const warehouses = Array.from(
        new Set(
            CURRENT_ITEMS
                .map(function (i) { return i.warehouse; })
                .filter(Boolean)
        )
    ).sort();

    populateWarehouseDropdown(warehouses);

    if (FILTERS.warehouse !== '__ALL__' && !warehouses.includes(FILTERS.warehouse)) {
        FILTERS.warehouse = '__ALL__';
        const warehouseEl = document.getElementById('warehouse-filter');
        if (warehouseEl) warehouseEl.value = '__ALL__';
    }

    renderProjectOptions();

    const filtered = CURRENT_ITEMS.filter(function (item) {
        const available = getAvailable(item);
        const cleanedName = cleanItemName(item.item_name, item.item_group || CURRENT_GROUP);
        const typeLabel = getTypeLabel(item);

        const searchText = (
            String(item.item_code || '') + ' ' +
            String(cleanedName || '') + ' ' +
            String(typeLabel || '') + ' ' +
            String(item.yield_to_hash || '') + ' ' +
            String(item.hash_to_rosin || '')
        ).toLowerCase();

        if (FILTERS.warehouse !== '__ALL__' && String(item.warehouse || '').trim() !== FILTERS.warehouse) {
            return false;
        }

        if (FILTERS.search && !searchText.includes(FILTERS.search)) {
            return false;
        }

        if (FILTERS.onlyAvailable && available <= 0) {
            return false;
        }

        if (FILTERS.lowStockOnly && !(available > 0 && available <= LOW_STOCK_THRESHOLD)) {
            return false;
        }

        return true;
    });

    CURRENT_FILTERED_ITEMS = filtered;
    renderSummary(filtered);
    renderStockTable(filtered);
}

// The group's projects with stock showing on the dashboard, from the server.
function setGroupProjects(projects) {
    const seen = {};
    GROUP_PROJECTS = [];
    // Fresh Frozen loads three groups; one project can be in several.
    projects.forEach(function (p) {
        if (!p || !p.name) return;
        if (!seen[p.name]) {
            seen[p.name] = { name: p.name, project_name: p.project_name || p.name, warehouses: [] };
            PROJECT_LABELS[p.name] = seen[p.name].project_name;
            GROUP_PROJECTS.push(seen[p.name]);
        }
        (p.warehouses || []).forEach(function (w) {
            if (!seen[p.name].warehouses.includes(w)) seen[p.name].warehouses.push(w);
        });
    });
}

// Only the projects with stock in the chosen warehouse (all of the group's
// with All Warehouses). A project already picked stays listed and selected,
// even where it holds nothing, so the choice is never silently dropped.
function renderProjectOptions() {
    const options = GROUP_PROJECTS.filter(function (p) {
        return FILTERS.warehouse === '__ALL__' || (p.warehouses || []).includes(FILTERS.warehouse);
    });
    if (FILTERS.project !== '__ALL__' && !options.some(function (p) { return p.name === FILTERS.project; })) {
        options.push({ name: FILTERS.project, project_name: getProjectLabel(FILTERS.project) });
    }
    options.sort(function (a, b) {
        return String(a.project_name).localeCompare(String(b.project_name), undefined, { numeric: true });
    });

    let html = '<option value="__ALL__">All Projects</option>';
    options.forEach(function (p) {
        html += `<option value="${escapeHtml(p.name)}">${escapeHtml(p.project_name || p.name)}</option>`;
    });

    const projectEl = document.getElementById('project-filter');
    if (projectEl) {
        projectEl.innerHTML = html;
        projectEl.value = FILTERS.project;
    }
}

function getProjectLabel(project) {
    return PROJECT_LABELS[project] || project;
}

function projectHeadingSuffix() {
    return FILTERS.project !== '__ALL__' ? ' · ' + getProjectLabel(FILTERS.project) : '';
}

function populateWarehouseDropdown(warehouses) {
    let html = '<option value="__ALL__">All Warehouses</option>';

    warehouses.forEach(function (w) {
        html += `<option value="${escapeHtml(w)}">${escapeHtml(w)}</option>`;
    });

    const warehouseEl = document.getElementById('warehouse-filter');
    if (warehouseEl) {
        warehouseEl.innerHTML = html;

        if (FILTERS.warehouse === '__ALL__' || warehouses.includes(FILTERS.warehouse)) {
            warehouseEl.value = FILTERS.warehouse;
        } else {
            warehouseEl.value = '__ALL__';
        }
    }
}

// ---------------------------------------------------
// SUMMARY
// ---------------------------------------------------

function renderSummary(items) {
    let totalQty = 0;
    let totalAvailable = 0;
    let low = 0;

    items.forEach(function (item) {
        const qty = parseNum(item.actual_qty);
        const available = getAvailable(item);

        totalQty += qty;
        totalAvailable += available;

        if (available > 0 && available <= LOW_STOCK_THRESHOLD) {
            low++;
        }
    });

    document.getElementById('total-items').innerText = items.length.toLocaleString('en-US');
    document.getElementById('total-qty').innerText = fmtQty(totalQty);
    document.getElementById('available-qty').innerText = fmtQty(totalAvailable);
    document.getElementById('low-stock').innerText = low;
}

