// ---------------------------------------------------
// CSV EXPORT
// ---------------------------------------------------

function exportCurrentViewToCSV() {
    if (!CURRENT_FILTERED_ITEMS || !CURRENT_FILTERED_ITEMS.length) {
        frappe.show_alert({
            message: 'No rows available to export',
            indicator: 'orange'
        });
        return;
    }

    const isFreshFrozen = isFreshFrozenCombinedView(CURRENT_GROUP);
    const rows = [];
    const header = [];

    header.push('Item Code');
    header.push('Item Name');

    if (isFreshFrozen) {
        header.push('Type');
        header.push('Yield To Hash%');
        header.push('Hash to Rosin%');
    }

    const projectLabel = FILTERS.project !== '__ALL__' ? getProjectLabel(FILTERS.project) : '';

    header.push('Warehouse');
    if (projectLabel) header.push('Project');
    header.push('Qty');
    header.push('Reserved');
    header.push('Available');
    header.push('Status');

    rows.push(header);

    CURRENT_FILTERED_ITEMS.forEach(function (item) {
        const row = [];
        const available = getAvailable(item);

        row.push(item.item_code || '');
        row.push(cleanItemName(item.item_name, item.item_group || CURRENT_GROUP));

        if (isFreshFrozen) {
            row.push(getTypeLabel(item));
            row.push(item.yield_to_hash || '');
            row.push(item.hash_to_rosin || '');
        }

        row.push(item.warehouse || '');
        if (projectLabel) row.push(projectLabel);
        row.push(parseNum(item.actual_qty).toFixed(2));
        row.push(parseNum(item.reserved_qty).toFixed(2));
        row.push(available.toFixed(2));
        row.push(getStatusLabel(available));

        rows.push(row);
    });

    const csvContent = rows
        .map(function (row) {
            return row.map(csvEscape).join(',');
        })
        .join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    const safeGroupName = String((CURRENT_GROUP || 'inventory') + (projectLabel ? ' ' + projectLabel : ''))
        .replace(/\s+/g, '_')
        .replace(/[^\w\-]/g, '');

    link.href = url;
    link.download = safeGroupName + '_inventory.csv';
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    frappe.show_alert({
        message: 'CSV exported successfully',
        indicator: 'green'
    });
}

// ---------------------------------------------------
// UTILITIES
// ---------------------------------------------------

function copyText(text) {
    if (!text) return;

    if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(text).then(function () {
            frappe.show_alert({
                message: 'Copied: ' + text,
                indicator: 'green'
            });
        }).catch(function () {
            fallbackCopyText(text);
        });
    } else {
        fallbackCopyText(text);
    }
}

function fallbackCopyText(text) {
    const temp = document.createElement('input');
    temp.value = text;
    document.body.appendChild(temp);
    temp.select();
    temp.setSelectionRange(0, 99999);

    try {
        document.execCommand('copy');
        frappe.show_alert({
            message: 'Copied: ' + text,
            indicator: 'green'
        });
    } catch (e) {
        frappe.show_alert({
            message: 'Could not copy item code',
            indicator: 'red'
        });
    }

    document.body.removeChild(temp);
}

// ---------------------------------------------------
// REMEMBERED GROUP
// ---------------------------------------------------

// The open group is kept in the URL hash (so a refresh or a shared link
// reopens it) and in localStorage as a fallback for a bare /inventory-dashboard.
const GROUP_STORAGE_KEY = 'mtm_inventory_dashboard_group';

function storageGet(key) {
    try { return window.localStorage.getItem(key); } catch (e) { return null; }
}

function storageSet(key, value) {
    try {
        if (value === null || value === undefined) window.localStorage.removeItem(key);
        else window.localStorage.setItem(key, value);
    } catch (e) { /* private window / blocked storage: nothing to remember */ }
}

function getSavedGroup() {
    const match = /(?:^|[#&])group=([^&]*)/.exec(window.location.hash || '');
    if (match) {
        try { return decodeURIComponent(match[1]); } catch (e) { /* fall through */ }
    }
    return storageGet(GROUP_STORAGE_KEY);
}

function saveGroup(group) {
    storageSet(GROUP_STORAGE_KEY, group);
    try {
        history.replaceState(null, '', window.location.pathname + window.location.search + '#group=' + encodeURIComponent(group));
    } catch (e) { /* old browser: the localStorage copy still works */ }
}

function restoreSavedGroup(groups) {
    const saved = getSavedGroup();
    if (saved && groups.some(function (g) { return g.name === saved; })) {
        loadStock(saved);
    }
}

// ---------------------------------------------------
// ORDER CART
// ---------------------------------------------------

// Items picked from any group, kept in localStorage until saved as a draft
// Sales Order. Each line is one item in one warehouse.
const CART_STORAGE_KEY = 'mtm_inventory_dashboard_order';
const ORDER_API = 'cannabis_management.api.inventory_order.';

let ORDER_ENABLED = false;
let ORDER_CART = [];
let ORDER_FORM_OPTIONS = null;
let ORDER_ROW_LOOKUP = {};
// The access code, once the server accepts it. Memory only: a reload asks again.
let ORDER_CODE = null;

function cartKey(item) {
    return String(item.item_code || '') + '||' + String(item.warehouse || '');
}

function isInCart(key) {
    return ORDER_CART.some(function (line) { return line.key === key; });
}

function loadCart() {
    try {
        const lines = JSON.parse(storageGet(CART_STORAGE_KEY) || '[]');
        return Array.isArray(lines) ? lines.filter(function (l) { return l && l.item_code && l.warehouse; }) : [];
    } catch (e) {
        return [];
    }
}

function saveCart() {
    storageSet(CART_STORAGE_KEY, ORDER_CART.length ? JSON.stringify(ORDER_CART) : null);
    updateOrderButton();
}

function initOrderCart() {
    ORDER_CART = loadCart();

    // Guests can browse stock, but only a user who may create a Sales Order
    // gets the Add buttons and the order popup.
    if (!frappe.is_user_logged_in || !frappe.is_user_logged_in()) return;

    frappe.call({
        method: ORDER_API + 'get_order_form_options',
        callback: function (r) {
            const data = r && r.message;
            if (!data || !data.can_create) return;

            ORDER_FORM_OPTIONS = data;
            ORDER_ENABLED = true;
            ensureFloatingBar();

            const btn = document.getElementById('view-order-btn');
            if (btn) {
                btn.hidden = false;
                btn.addEventListener('click', openOrderModal);
            }
            updateOrderButton();
            bindOrderTableClicks();

            if (CURRENT_ITEMS && CURRENT_ITEMS.length) renderWithFilters();
        }
    });
}

function bindOrderTableClicks() {
    const table = document.getElementById('stock-table');
    if (!table) return;

    table.addEventListener('change', function (e) {
        const box = e.target.closest('.order-check');
        if (!box) return;

        const key = box.getAttribute('data-key');
        if (!box.checked) {
            removeFromCart(key);
            return;
        }
        if (isInCart(key)) return;

        const item = ORDER_ROW_LOOKUP[key];
        if (!item) return;

        ORDER_CART.push({
            key: key,
            item_code: item.item_code,
            item_name: cleanItemName(item.item_name, item.item_group || CURRENT_GROUP),
            item_group: item.item_group || CURRENT_GROUP,
            warehouse: item.warehouse,
            available: getAvailable(item),
            qty: ''
        });
        saveCart();
        setRowSelected(key, true);
    });
}

function removeFromCart(key) {
    ORDER_CART = ORDER_CART.filter(function (line) { return line.key !== key; });
    saveCart();
    setRowSelected(key, false);
    renderOrderLines();
}

function setRowSelected(key, inCart) {
    document.querySelectorAll('.order-check').forEach(function (box) {
        if (box.getAttribute('data-key') !== key) return;
        box.checked = inCart;
        const row = box.closest('tr');
        if (row) row.classList.toggle('row-selected', inCart);
    });
}

function renderOrderCell(item) {
    const key = cartKey(item);
    ORDER_ROW_LOOKUP[key] = item;

    return `
        <td class="order-check-col">
            <input type="checkbox" class="order-check" data-key="${escapeHtml(key)}"
                ${isInCart(key) ? 'checked' : ''}
                aria-label="Select ${escapeHtml(item.item_code || '')} for order">
        </td>
    `;
}

// ---------------------------------------------------
// ORDER POPUP
// ---------------------------------------------------

