};

function pluralize(n, word) {
    return n + ' ' + word + (n === 1 ? '' : 's');
}

function cartCompanies() {
    // Warehouse names end in the company abbreviation (" - MTM", " - TSBC").
    return Array.from(new Set(ORDER_CART.map(function (l) {
        return String(l.warehouse).split(' - ').pop();
    })));
}

function lineCurrencyInfo(line) {
    const abbr = String(line.warehouse || '').split(' - ').pop();
    const info = (ORDER_FORM_OPTIONS.currencies || {})[abbr];
    const currency = (info && info.currency) || ORDER_FORM_OPTIONS.default_currency || 'USD';
    return { abbr: abbr, currency: currency, symbol: (info && info.symbol) || currency };
}

function fmtMoney(amount, currency) {
    try {
        return new Intl.NumberFormat('en-US', { style: 'currency', currency: currency }).format(parseNum(amount));
    } catch (e) {
        return currency + ' ' + fmtQty(amount);
    }
}

function lineAmount(line) {
    return parseNum(line.qty) * parseNum(line.rate);
}

function selectHtml(id, fieldname) {
    const field = (ORDER_FORM_OPTIONS.options || {})[fieldname] || { options: [], default: '' };
    let html = `<select id="${id}" class="form-control of-control">`;
    if (!field.reqd) html += '<option value="">Select…</option>';
    field.options.forEach(function (opt) {
        html += `<option value="${escapeHtml(opt)}" ${opt === field.default ? 'selected' : ''}>${escapeHtml(opt)}</option>`;
    });
    return html + '</select>';
}

function fieldLabel(fieldname, fallback) {
    const field = (ORDER_FORM_OPTIONS.options || {})[fieldname];
    return escapeHtml((field && field.label) || fallback);
}

function ensureFloatingBar() {
    if (document.getElementById('order-float')) return;
    const bar = document.createElement('button');
    bar.type = 'button';
    bar.id = 'order-float';
    bar.className = 'mt-order-float';
    bar.hidden = true;
    bar.innerHTML = `
        <span class="mt-order-float-icon">${ORDER_ICONS.cart}</span>
        <span class="mt-order-float-text" id="order-float-text"></span>
        <span class="mt-order-float-cta">View Order ${ORDER_ICONS.arrow}</span>
    `;
    bar.addEventListener('click', openOrderModal);
    document.body.appendChild(bar);
}

function updateOrderButton() {
    const n = ORDER_CART.length;

    const countEl = document.getElementById('order-count');
    if (countEl) countEl.innerText = n;

    const btn = document.getElementById('view-order-btn');
    if (btn) btn.classList.toggle('has-items', n > 0);

    const bar = document.getElementById('order-float');
    const modal = document.getElementById('order-modal');
    if (bar) {
        bar.hidden = !ORDER_ENABLED || !n || (modal && !modal.hidden);
        const text = document.getElementById('order-float-text');
        if (text) text.innerText = pluralize(n, 'item') + ' selected';
    }

    updateOrderSubtitle();
}

function updateOrderSubtitle() {
    const sub = document.getElementById('order-modal-sub');
    if (!sub) return;
    const n = ORDER_CART.length;
    const companies = cartCompanies();
    sub.innerText = n
        ? pluralize(n, 'item') + (companies.length > 1 ? ' · ' + companies.length + ' companies' : '')
        : 'No items selected';
}

function ensureOrderModal() {
    if (document.getElementById('order-modal')) return;

    const today = ORDER_FORM_OPTIONS.today;
    let termsOptions = '<option value="">Select…</option>';
    (ORDER_FORM_OPTIONS.payment_terms_templates || []).forEach(function (t) {
        termsOptions += `<option value="${escapeHtml(t)}">${escapeHtml(t)}</option>`;
    });

    const modal = document.createElement('div');
    modal.id = 'order-modal';
    modal.className = 'mt-modal-backdrop';
    modal.hidden = true;
    modal.innerHTML = `
        <div class="mt-modal" role="dialog" aria-modal="true" aria-labelledby="order-modal-title">
            <div class="mt-modal-header">
                <div class="mt-modal-heading">
                    <span class="mt-modal-icon">${ORDER_ICONS.cart}</span>
                    <div>
                        <h4 id="order-modal-title">New Sales Order</h4>
                        <div class="mt-modal-sub" id="order-modal-sub"></div>
                    </div>
                </div>
                <div class="mt-modal-header-actions">
                    <span class="mt-draft-pill">Draft</span>
                    <button type="button" class="mt-modal-close" data-action="close" aria-label="Close">${ORDER_ICONS.close}</button>
                </div>
            </div>

            <div class="mt-modal-content" id="order-form-view">
                <section class="order-pane order-pane-items" aria-labelledby="order-items-title">
                    <div class="order-pane-head">
                        <h5 id="order-items-title">Items</h5>
                        <button type="button" class="mt-link-btn" data-action="clear">Clear all</button>
                    </div>
                    <div id="order-company-note" class="order-banner" hidden></div>
                    <div id="order-lines" class="order-lines"></div>
                    <div id="order-totals" class="order-totals" hidden></div>
                </section>

                <section class="order-pane order-pane-details" aria-labelledby="order-details-title">
                    <div class="order-pane-head">
                        <h5 id="order-details-title">Order Details</h5>
                    </div>

                    <div class="of-group">
                        <div class="of-group-title">Customer</div>
                        <div class="of-grid">
                            <div class="of-field of-wide">
                                <label for="of-customer">Customer <span class="of-reqd">*</span></label>
                                <input id="of-customer" class="form-control of-control" list="of-customer-list" autocomplete="off" placeholder="Search customers">
                                <datalist id="of-customer-list"></datalist>
                            </div>
                            <div class="of-field of-wide">
                                <label for="of-license">License</label>
                                <input id="of-license" class="form-control of-control" list="of-license-list" autocomplete="off" placeholder="Search licenses">
                                <datalist id="of-license-list"></datalist>
                            </div>
                        </div>
                    </div>

                    <div class="of-group">
                        <div class="of-group-title">Delivery</div>
                        <div class="of-grid">
                            <div class="of-field">
                                <label for="of-delivery-date">Delivery Date <span class="of-reqd">*</span></label>
                                <input id="of-delivery-date" type="date" class="form-control of-control" value="${escapeHtml(today)}" min="${escapeHtml(today)}">
                            </div>
                            <div class="of-field">
                                <label for="of-pickup">${fieldLabel('custom_pickup_or_dropoff', 'Pickup or Dropoff')}</label>
                                ${selectHtml('of-pickup', 'custom_pickup_or_dropoff')}
                            </div>
                            <div class="of-field of-wide">
                                <label for="of-logistic">${fieldLabel('custom_logistic_status', 'Logistic Status')}</label>
                                ${selectHtml('of-logistic', 'custom_logistic_status')}
                            </div>
                        </div>
                    </div>

                    <div class="of-group">
                        <div class="of-group-title">Order &amp; Payment</div>
                        <div class="of-grid">
                            <div class="of-field">
                                <label for="of-so-type">${fieldLabel('custom_sales_order_type', 'Sales Order Type')}</label>
                                ${selectHtml('of-so-type', 'custom_sales_order_type')}
                            </div>
                            <div class="of-field">
                                <label for="of-order-type">${fieldLabel('order_type', 'Order Type')}</label>
                                ${selectHtml('of-order-type', 'order_type')}
                            </div>
                            <div class="of-field">
                                <label for="of-mop">${fieldLabel('custom_mode_of_payment', 'Mode of Payment')} <span class="of-reqd">*</span></label>
                                ${selectHtml('of-mop', 'custom_mode_of_payment')}
                            </div>
                            <div class="of-field" id="of-terms-wrap" hidden>
                                <label for="of-terms">Payment Terms</label>
                                <select id="of-terms" class="form-control of-control">${termsOptions}</select>
