                    </div>

                    <div class="of-group">
                        <div class="of-group-title">Notes</div>
                        <div class="of-grid">
                            <div class="of-field of-wide">
                                <label for="of-logistics-notes">Notes for Logistics</label>
                                <textarea id="of-logistics-notes" class="form-control of-control" rows="2"></textarea>
