                    <p>Orders are protected. Enter the code to view and save this order.</p>
                    <input id="order-lock-input" type="password" class="form-control order-lock-input"
                        inputmode="numeric" autocomplete="off" placeholder="••••••" aria-label="Access code">
                    <div class="order-lock-error" id="order-lock-error" role="alert" hidden></div>
                    <div class="order-lock-actions">
                        <button type="button" class="btn mt-cancel-btn" data-action="close">Cancel</button>
                        <button type="submit" class="btn mt-save-btn" id="order-lock-btn">Unlock</button>
                    </div>
