            </div>

            <div class="mt-modal-footer" id="order-footer">
                <div id="order-error" class="order-error" role="alert" hidden></div>
                <div class="mt-modal-hint">Saved as a draft. Review and submit it in the ERP.</div>
                <span class="mt-modal-spacer"></span>
                <button type="button" class="btn mt-cancel-btn" data-action="close">Close</button>
                <button type="button" class="btn mt-save-btn" id="order-save-btn" data-action="save">
                    Save as Draft ${ORDER_ICONS.arrow}
                </button>
            </div>
        </div>
