    // On <body>, not inside the page: the theme's navbar (z-index 1050) would
    // otherwise cover the popup.
    document.body.appendChild(modal);

    modal.addEventListener('click', function (e) {
        if (e.target === modal) return closeOrderModal();
        const actionEl = e.target.closest('[data-action]');
        if (actionEl) {
            const action = actionEl.getAttribute('data-action');
            if (action === 'close') closeOrderModal();
            else if (action === 'clear') clearOrderLines();
            else if (action === 'save') saveOrder();
            else if (action === 'new') showOrderFormView();
            return;
        }
        const removeBtn = e.target.closest('.ol-remove');
        if (removeBtn) removeFromCart(removeBtn.getAttribute('data-key'));
    });

    modal.addEventListener('input', function (e) {
        const target = e.target;
        if (target.classList.contains('of-control')) {
            target.classList.remove('is-invalid');
            showOrderError('');
        }

        const isQty = target.classList.contains('ol-qty');
        if (!isQty && !target.classList.contains('ol-rate')) return;

        const key = target.getAttribute('data-key');
        const line = ORDER_CART.find(function (l) { return l.key === key; });
        if (!line) return;

        if (isQty) {
            line.qty = target.value;
            target.classList.remove('is-invalid');
            updateLineWarning(target.closest('.ol-card'), line);
        } else {
            line.rate = target.value;
        }
        const subtotal = target.closest('.ol-card').querySelector('.ol-subtotal strong');
        if (subtotal) subtotal.innerText = fmtMoney(lineAmount(line), lineCurrencyInfo(line).currency);
        saveCart();
        renderOrderTotals();
    });

    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape' && !modal.hidden) closeOrderModal();
    });

    const customerEl = document.getElementById('of-customer');
    const licenseEl = document.getElementById('of-license');

    customerEl.addEventListener('input', debounce(function () {
        fillDatalist('search_customers', customerEl.value, 'of-customer-list', 'customer_name');
    }, 250));
    licenseEl.addEventListener('input', debounce(function () {
        fillDatalist('search_licenses', licenseEl.value, 'of-license-list', 'licence_name');
    }, 250));

    document.getElementById('of-mop').addEventListener('change', toggleTermsField);
    toggleTermsField();

    document.getElementById('order-lock-form').addEventListener('submit', submitOrderCode);
}

function setOrderLocked(locked) {
    const box = document.querySelector('#order-modal .mt-modal');
    if (!box) return;
    box.classList.toggle('is-locked', locked);
    // inert keeps the blurred form out of reach of the keyboard as well.
    ['order-form-view', 'order-footer', 'order-success-view'].forEach(function (id) {
        const el = document.getElementById(id);
        if (!el) return;
        if (locked) el.setAttribute('inert', '');
        else el.removeAttribute('inert');
    });
    document.getElementById('order-lock').hidden = !locked;

    if (locked) {
        const input = document.getElementById('order-lock-input');
        input.value = '';
        showLockError('');
        setTimeout(function () { input.focus(); }, 30);
    }
}

function showLockError(message) {
    const el = document.getElementById('order-lock-error');
    if (!el) return;
    el.hidden = !message;
    el.innerText = message || '';
}

function submitOrderCode(e) {
    e.preventDefault();
    const input = document.getElementById('order-lock-input');
    const code = input.value.trim();
    if (!code) return showLockError('Enter the access code.');

    frappe.call({
        method: ORDER_API + 'verify_order_code',
        args: { code: code },
        btn: document.getElementById('order-lock-btn'),
        callback: function (r) {
            if (r && r.message && r.message.ok) {
                ORDER_CODE = code;
                setOrderLocked(false);
                fillDatalist('search_customers', '', 'of-customer-list', 'customer_name');
                fillDatalist('search_licenses', '', 'of-license-list', 'licence_name');
                const customerEl = document.getElementById('of-customer');
                if (ORDER_CART.length && !customerEl.value) customerEl.focus();
                return;
            }
            input.value = '';
            input.focus();
            showLockError('Wrong code. Try again.');
            const card = document.querySelector('.order-lock-card');
            card.classList.remove('shake');
            void card.offsetWidth;
            card.classList.add('shake');
        }
    });
}

function toggleTermsField() {
    const mop = document.getElementById('of-mop');
    const wrap = document.getElementById('of-terms-wrap');
    if (mop && wrap) wrap.hidden = mop.value !== 'Payment Terms';
}

function fillDatalist(method, txt, listId, labelField) {
    frappe.call({
        method: ORDER_API + method,
        args: { txt: txt || '', code: ORDER_CODE },
        callback: function (r) {
            const list = document.getElementById(listId);
            if (!list) return;
            list.innerHTML = (r.message || []).map(function (row) {
                const label = row[labelField] && row[labelField] !== row.name ? row[labelField] : '';
                return `<option value="${escapeHtml(row.name)}">${escapeHtml(label)}</option>`;
            }).join('');
        }
    });
}

function openOrderModal() {
    if (!ORDER_ENABLED) return;
    ensureOrderModal();
    showOrderFormView();

    const modal = document.getElementById('order-modal');
    modal.hidden = false;
    document.body.classList.add('mt-modal-open');
    updateOrderButton();

    setOrderLocked(!ORDER_CODE);
    if (ORDER_CODE) {
        const customerEl = document.getElementById('of-customer');
        if (ORDER_CART.length && !customerEl.value) customerEl.focus();
    }
}

function closeOrderModal() {
    const modal = document.getElementById('order-modal');
    if (modal) modal.hidden = true;
    document.body.classList.remove('mt-modal-open');
    updateOrderButton();
}

function showOrderFormView() {
    document.getElementById('order-form-view').hidden = false;
    document.getElementById('order-footer').hidden = false;
    document.getElementById('order-success-view').hidden = true;
    showOrderError('');
    renderOrderLines();
}

function updateLineWarning(card, line) {
    if (!card) return;
    const over = parseNum(line.qty) > parseNum(line.available);
    card.classList.toggle('is-over', over);
    const warn = card.querySelector('.ol-warn');
    if (warn) warn.hidden = !over;
}

function renderOrderLines() {
    const wrap = document.getElementById('order-lines');
    if (!wrap) return;

    updateOrderSubtitle();

    const note = document.getElementById('order-company-note');
    const companies = cartCompanies();
    note.hidden = companies.length < 2;
    note.innerHTML = `${ORDER_ICONS.info}<span>These items are in warehouses of <strong>${companies.length} companies</strong> (${escapeHtml(companies.join(', '))}). One draft Sales Order is saved for each company.</span>`;

    renderOrderTotals();

    if (!ORDER_CART.length) {
        wrap.innerHTML = `
            <div class="order-empty">
                <span class="order-empty-icon">${ORDER_ICONS.box}</span>
                <strong>No items selected</strong>
                <span>Tick the box next to an item code, in any item group, to add it here.</span>
            </div>
        `;
        return;
    }

    const canRate = !!ORDER_FORM_OPTIONS.can_set_rate;

    wrap.innerHTML = ORDER_CART.map(function (line) {
        const over = parseNum(line.qty) > parseNum(line.available);
        const available = fmtQty(line.available);
        const cur = lineCurrencyInfo(line);
        return `
            <div class="ol-card ${over ? 'is-over' : ''}">
                <div class="ol-main">
                    <div class="ol-name">${escapeHtml(line.item_name)}</div>
                    <div class="ol-meta">
                        <span class="ol-code">${escapeHtml(line.item_code)}</span>
                        ${line.item_group ? `<span class="ol-chip">${escapeHtml(line.item_group)}</span>` : ''}
                    </div>
                    <div class="ol-stock">${escapeHtml(line.warehouse)} · <strong>${available}</strong> available</div>
                </div>
                <div class="ol-inputs">
                    <label class="ol-input">
                        <span>Qty</span>
                        <input type="number" min="0" step="any" inputmode="decimal" class="form-control ol-qty"
                            data-key="${escapeHtml(line.key)}" value="${escapeHtml(line.qty)}" placeholder="0">
                    </label>
                    ${canRate ? `
                    <label class="ol-input">
                        <span>Rate (${escapeHtml(cur.currency)})</span>
                        <span class="ol-money">
                            <span class="ol-currency" aria-hidden="true">${escapeHtml(cur.symbol)}</span>
                            <input type="number" min="0" step="any" inputmode="decimal" class="form-control ol-rate"
                                data-key="${escapeHtml(line.key)}" value="${escapeHtml(line.rate || '')}" placeholder="0.00">
                        </span>
                    </label>` : ''}
                    <button type="button" class="ol-remove" data-key="${escapeHtml(line.key)}"
                        title="Remove" aria-label="Remove ${escapeHtml(line.item_name)}">${ORDER_ICONS.trash}</button>
                </div>
                <div class="ol-warn" ${over ? '' : 'hidden'}>More than the ${available} available</div>
                ${canRate ? `<div class="ol-subtotal">Subtotal <strong>${fmtMoney(lineAmount(line), cur.currency)}</strong></div>` : ''}
            </div>
        `;
    }).join('');
}

function renderOrderTotals() {
    const el = document.getElementById('order-totals');
    if (!el) return;
    el.hidden = !ORDER_CART.length;
    if (!ORDER_CART.length) return;

    let html = `<div class="ot-row"><span>Items</span><strong>${ORDER_CART.length}</strong></div>`;

    if (!ORDER_FORM_OPTIONS.can_set_rate) {
        el.innerHTML = html + '<div class="ot-note">Rates are filled in on the Sales Order by a Sales Manager.</div>';
        return;
    }

    // One draft is saved per company, so show each company's subtotal when
    // the cart spans more than one; the total adds them up per currency.
    const byCompany = {};
    const byCurrency = {};
    ORDER_CART.forEach(function (line) {
        const cur = lineCurrencyInfo(line);
        const key = cur.abbr + '||' + cur.currency;
        byCompany[key] = (byCompany[key] || 0) + lineAmount(line);
        byCurrency[cur.currency] = (byCurrency[cur.currency] || 0) + lineAmount(line);
    });

    const companyKeys = Object.keys(byCompany);
    companyKeys.forEach(function (key) {
        const parts = key.split('||');
        const label = companyKeys.length > 1 ? 'Subtotal · ' + escapeHtml(parts[0]) : 'Subtotal';
        html += `<div class="ot-row"><span>${label}</span><strong>${fmtMoney(byCompany[key], parts[1])}</strong></div>`;
    });

    const total = Object.keys(byCurrency).map(function (c) { return fmtMoney(byCurrency[c], c); }).join(' + ');
    html += `<div class="ot-row ot-total"><span>Total</span><strong>${total}</strong></div>`;
    html += '<div class="ot-note">Taxes, if the customer has any, are added when the order is saved.</div>';
    el.innerHTML = html;
}

function clearOrderLines() {
    if (!ORDER_CART.length) return;
    if (!window.confirm('Remove all ' + pluralize(ORDER_CART.length, 'item') + ' from this order?')) return;
    const keys = ORDER_CART.map(function (l) { return l.key; });
    ORDER_CART = [];
    saveCart();
    keys.forEach(function (key) { setRowSelected(key, false); });
    renderOrderLines();
}

function showOrderError(message, field) {
    const el = document.getElementById('order-error');
    if (!el) return;
    el.hidden = !message;
    el.innerText = message || '';
    if (field) {
        field.classList.add('is-invalid');
        field.focus();
        if (field.scrollIntoView) field.scrollIntoView({ block: 'center', behavior: 'smooth' });
    }
}

function readOrderForm() {
    const val = function (id) {
        const el = document.getElementById(id);
        return el ? String(el.value || '').trim() : '';
    };
    const mop = val('of-mop');
    return {
        customer: val('of-customer'),
        custom_license: val('of-license'),
        delivery_date: val('of-delivery-date'),
        custom_pickup_or_dropoff: val('of-pickup'),
        custom_logistic_status: val('of-logistic'),
        custom_sales_order_type: val('of-so-type'),
        order_type: val('of-order-type'),
        custom_mode_of_payment: mop,
        payment_terms_template: mop === 'Payment Terms' ? val('of-terms') : '',
        custom_notes_for_logistics: val('of-logistics-notes'),
        custom_planner_notes: val('of-planner-notes')
    };
}

function resetOrderForm() {
    ['of-customer', 'of-license', 'of-logistics-notes', 'of-planner-notes', 'of-terms'].forEach(function (id) {
        const el = document.getElementById(id);
        if (el) el.value = '';
    });
    [['of-so-type', 'custom_sales_order_type'], ['of-mop', 'custom_mode_of_payment'],
     ['of-pickup', 'custom_pickup_or_dropoff'], ['of-logistic', 'custom_logistic_status'],
     ['of-order-type', 'order_type']].forEach(function (pair) {
        const el = document.getElementById(pair[0]);
        const field = (ORDER_FORM_OPTIONS.options || {})[pair[1]];
        if (el) el.value = (field && field.default) || '';
    });
    document.getElementById('of-delivery-date').value = ORDER_FORM_OPTIONS.today;
    document.querySelectorAll('#order-modal .is-invalid').forEach(function (el) { el.classList.remove('is-invalid'); });
    toggleTermsField();
}

function showOrderSuccess(created) {
    const many = created.length > 1;
    const cards = created.map(function (so) {
        return `
            <a class="order-success-card" href="/app/sales-order/${encodeURIComponent(so.name)}" target="_blank" rel="noopener">
                <span class="order-success-name">${escapeHtml(so.name)}</span>
                <span class="order-success-meta">${escapeHtml(so.company)} · ${pluralize(so.items, 'item')} · ${fmtMoney(so.grand_total, so.currency)}</span>
                <span class="order-success-open">Open ${ORDER_ICONS.arrow}</span>
            </a>
        `;
    }).join('');

    const view = document.getElementById('order-success-view');
    view.innerHTML = `
        <div class="order-success-badge">${ORDER_ICONS.check}</div>
        <h4>${many ? created.length + ' draft Sales Orders saved' : 'Draft Sales Order saved'}</h4>
        <p>${many ? 'One order for each company. ' : ''}Open ${many ? 'them' : 'it'} in the ERP to review and submit.</p>
        <div class="order-success-list">${cards}</div>
        <div class="order-success-actions">
            <button type="button" class="btn mt-cancel-btn" data-action="new">Start a new order</button>
            <button type="button" class="btn mt-save-btn" data-action="close">Done</button>
        </div>
    `;

    document.getElementById('order-form-view').hidden = true;
    document.getElementById('order-footer').hidden = true;
    view.hidden = false;
    updateOrderSubtitle();
}

function saveOrder() {
    showOrderError('');

    if (!ORDER_CART.length) {
        return showOrderError('Select at least one item for the order.');
    }

    const missingQty = ORDER_CART.find(function (l) { return !(parseNum(l.qty) > 0); });
    if (missingQty) {
        const input = document.querySelector('.ol-qty[data-key="' + CSS.escape(missingQty.key) + '"]');
        return showOrderError('Enter a qty for ' + missingQty.item_name + '.', input);
    }

    const details = readOrderForm();
    if (!details.customer) return showOrderError('Select a customer.', document.getElementById('of-customer'));
    if (!details.delivery_date) return showOrderError('Set a delivery date.', document.getElementById('of-delivery-date'));
    if (!details.custom_mode_of_payment) return showOrderError('Select a mode of payment.', document.getElementById('of-mop'));

    frappe.call({
        method: ORDER_API + 'create_draft_sales_orders',
        args: {
            items: ORDER_CART.map(function (l) {
                return { item_code: l.item_code, warehouse: l.warehouse, qty: parseNum(l.qty), rate: parseNum(l.rate) };
            }),
            details: details,
            code: ORDER_CODE
        },
        btn: document.getElementById('order-save-btn'),
        freeze: true,
        callback: function (r) {
            const created = (r && r.message) || [];
            if (!created.length) return;

            const keys = ORDER_CART.map(function (l) { return l.key; });
            ORDER_CART = [];
            saveCart();
            keys.forEach(function (key) { setRowSelected(key, false); });
            resetOrderForm();
            showOrderSuccess(created);
        }
    });
}

